/**
 * Fonty pro náhledový obrázek, zapečené jako base64.
 *
 * Edge runtime nemá přístup k souborovému systému, takže se font nedá načíst
 * z disku. Satori navíc neumí WOFF2 — proto TTF, subsetovaný na ASCII a
 * českou diakritiku (326 kB → ~13 kB na řez).
 *
 * Generováno, needitovat ručně. Postup je v README.
 */

function decode(base64: string): ArrayBuffer {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

